import json,csv,collections
from pathlib import Path
base=Path.cwd();root=base/'artifacts/experiment-01-v4-results';out=base/'reports/experiment-01-v4'
metrics=json.loads((out/'metrics.json').read_text());unresolved=json.loads((out/'unresolved.json').read_text());ledger=json.loads((out/'ledger-final.json').read_text())
order=lambda r: 2 if '-repeat-' in r['run_id'] else 1 if '-confirmation-' in r['run_id'] else 0
metrics.sort(key=order)
labels=['Selection','Confirmation','Selection repeat']
def label(r):return labels[order(r)]
def link(text,p):return f'[{text}]({p})'
lines=['# Experiment 1 — protocol-v4 results','', '**Status: stopped at the baseline coverage gate; the full throughput study is incomplete.** All 149 prescribed baseline episodes finished. The eight throughput arms (512 episodes) were not launched. No training or optimizer updates occurred.','', 'The procedure requires at least 95% scoring coverage (31/32 selection, 81/85 confirmation) before a reliable comparison. The initial selection and confirmation both failed. The single preplanned selection repeat was retained to quantify variability; it does not replace the first result. No questions were removed, no unresolved score was converted to a zero training reward, and no grader, rubric, protocol or budget was changed to force a pass.','', '## Baseline results','', '| Cohort | Scored | Coverage | Completed answers | Demonstrated quality | Resolved mean | Wall time |','|---|---:|---:|---:|---:|---:|---:|']
per_task=[];reports={}
for r in metrics:
 n=r['attempted'];reports[label(r)]=json.loads(Path(r['evaluation_file']).read_text())
 lines.append(f"| {label(r)} | {r['resolved']}/{n} | {r['scoring_coverage']:.2%} | {r['completed']}/{n} ({r['completion_rate']:.2%}) | {r['demonstrated_quality']:.2%} | {r['resolved_mean']:.2%} | {r['wall_seconds']:.2f} s |")
 for x in reports[label(r)]['results']:per_task.append({'cohort':label(r),**{k:x[k] for k in ['task_id','episode_id','family_id','status','reward','termination']}})
lines+=['','Demonstrated quality is the sum of resolved quality scores divided by all assigned tasks. Missing grades remain null; they contribute no demonstrated points. This is an uncalibrated reference-grader endpoint, not an accepted-answer rate or independently verified correctness. All observed resolved scores were 0 or 1.','', 'The same unchanged Qwen/Qwen3.5-4B policy was evaluated at temperature 0 with Qwen/Qwen3.5-397B-A17B, protocol experimental-reference-v4, four judge slots and 32 rollout slots. Inference/grader scheduling can still vary. The frozen dataset contains 858 training and 117 development tasks; selection and confirmation are task-disjoint but share repository families. These are repurposed benchmark questions, not an untouched final test set.','', '## Repeat and unresolved sensitivity','']
if 'Selection repeat' in reports:
 a={x['task_id']:x for x in reports['Selection']['results']};b={x['task_id']:x for x in reports['Selection repeat']['results']};assert set(a)==set(b)
 matched=[i for i in a if a[i]['status']==b[i]['status']=='resolved'];delta=sum(b[i]['reward']-a[i]['reward'] for i in matched)/len(matched)
 lines.append(f"The repeat changed demonstrated quality from {metrics[0]['demonstrated_quality']:.2%} to {metrics[2]['demonstrated_quality']:.2%}. Both runs resolved {len(matched)} matched tasks; their mean repeat-minus-initial difference was {delta:+.4f}. These are repeated observations of the same model, not learning gains. No confidence or noninferiority claim is made.")
lines.append('')
for r in metrics:
 lines.append(f"- {label(r)}: assigning unresolved tasks anywhere in [0,1] gives an overall-quality sensitivity range of {r['demonstrated_quality']:.2%}–{r['demonstrated_quality']+(r['attempted']-r['resolved'])/r['attempted']:.2%}.")
lines+=['','## Why coverage failed','', 'The following counts describe failures, not corrections to confirmation questions. Confirmation contents were not used to tune the protocol.','', '| Failure | Episodes |','|---|---:|']
counts=collections.Counter((x['error'] or {}).get('detail','; '.join(x['reasons'])) for x in unresolved)
for k,v in counts.items():lines.append(f'| {k} | {v} |')
lines+=['',link('Detailed unresolved records',out/'unresolved.json')+'. Selection-only diagnosis found ambiguity about the reference/source support, an evidence payload exceeding the fixed byte limit, and a supported assertion without verified evidence keys. Reference ambiguity cannot safely be repaired by automatically assigning a score. Truncation and evidence-size failures require a versioned evidence/grading design and fresh controls.','', '## Runtime and cost','', '| Cohort | Completed/min | Scored/min | Output tokens/s | Latency p50 / p95 | Episode reservations |','|---|---:|---:|---:|---:|---:|']
for r in metrics:lines.append(f"| {label(r)} | {r['completed_per_minute']:.2f} | {r['resolved_per_minute']:.2f} | {r['tokens_per_second']:.2f} | {r['latency_p50']:.2f} / {r['latency_p95']:.2f} s | ${r['reserved_episode_cost_usd']:.4f} |")
lines+=['','Reported wall time runs from evaluation dispatch through the final episode’s grading and cleanup; model/tokenizer/controller startup and W&B finalization are outside this timer. Startup was not separately instrumented, so no cold-start comparison is claimed. Latencies include grading and its queue; the 300-second action-loop limit is not a deadline on subsequent grading.','', '| Cohort | Provisioning sum | Generation sum | Tools sum | Verification sum | Judge queue sum | Judge sampling sum |','|---|---:|---:|---:|---:|---:|---:|']
for r in metrics:
 t=r['timing_sum_seconds'];lines.append(f"| {label(r)} | {t['provision_seconds']:.2f} s | {t['generation_seconds']:.2f} s | {t['action_seconds']:.2f} s | {t['verification_seconds']:.2f} s | {r['judge_queue_seconds']:.2f} s | {r['judge_sampling_seconds']:.2f} s |")
lines+=['', '| Cohort | Invalid actions | Episodes with failed citation links / audited | Tool/provider error terminations | Tracking failures |', '|---|---:|---:|---:|---:|']
for r in metrics:
 lines.append(f"| {label(r)} | {r['invalid_action_events']} | {r['episodes_with_failed_citation_links']}/{r['episodes_with_semantic_citation_audit']} | {r['provider_or_tool_error_terminations']} | {r['tracking_failures']} |")
lines+=['', 'Citation counts include only episodes with a semantic citation audit; missing audits are not treated as successful citations. No final episode ended with an infrastructure-error or agent-error termination.']
prior=37.829845229999826;total=ledger['reserved_usd'];new=total-prior
lines+=['','Stage values sum work across overlapping episodes and must not be added to obtain coordinator wall time. Judge queue and sampling are included within verification. Cleanup is included in per-episode timing; the repository sandbox is closed before grading.','',f"New Experiment 1 reservations: **${new:.4f}**, including controller allowances. Prior ledger reservations: **${prior:.4f}**. Cumulative Experiment 1 ledger: **${total:.4f} / $300**, leaving **${300-total:.4f}** under that cap. These conservative reservations are not provider invoices. Actual billing remains unavailable; image builds and persistent-volume storage are not fully metered by this ledger and use the project infrastructure reserve. The $1,000 project allocation was not increased.",'','Prices were rechecked against [Tinker’s model catalog](https://tinker-docs.thinkingmachines.ai/tinker/models.json) and [Modal pricing](https://modal.com/pricing); they matched the frozen configuration. '+link('Final ledger snapshot',out/'ledger-final.json')+'.','', '## Logs and reproducible artifacts','']
for r in metrics:
 rid=r['run_id'];t=r['tracking_ids'][0];url='https://wandb.ai/nmdatar-harvard-university/repository-qa-training/runs/'+t
 logs=list(root.glob('campaigns/*/'+rid+'.log'));run=root/'artifacts/experiments'/rid
 lines.append(f"- **{label(r)}:** {link('W&B',url)} · {link('controller log',logs[0])} · {link('evaluation JSON',base/r['evaluation_file'])} · {link('events',run/'events.jsonl')} · {link('answers',run/'answers.json')}")
lines+=['',link('Per-task CSV',out/'per-task.csv')+' · '+link('Full metrics JSON',out/'metrics.json')+' · '+link('Frozen specification',out/'specification.json')+' · '+link('Artifact checksums',out/'checksums.json'),'', 'W&B Tables → answers contains submissions, rewards, grading status/reason, phase and optimizer step. Private raw judge responses and full trajectories are retained in the local downloaded artifact directory and the private Modal volume `repository-qa-training-state-v2`.','', '## Decision','', 'Do not advance to GRPO or select a throughput winner from these results. Answer completion passed 90% on the initial cohorts, but scoring coverage failed 95%. The provisional 32-rollout setting is therefore not a benchmark-selected concurrency. No 16-task × 4-attempt update-cost estimate or full-dataset runtime extrapolation is justified without the unrun repeated throughput arms.','', 'A continuation needs an independently justified, versioned grader/evidence repair and fresh baseline controls while preserving the failed runs. The frozen cohorts must not be edited based on these scores. The original full Experiment 1 remains incomplete; this report records a completed baseline attempt with a failed readiness gate.']
with (out/'per-task.csv').open('w') as f:
 w=csv.DictWriter(f,fieldnames=list(per_task[0]));w.writeheader();w.writerows(per_task)
(out/'README.md').write_text('\n'.join(lines)+'\n')
print('Report written:',out/'README.md')
